exercises.solution:
function formatarReais(centavos) {
  return `R$ ${(centavos / 100).toFixed(2).replace('.', ',')}`;
}

function resumoDaCompra(itens, totalCentavos, temCartao) {
  const desconto = temCartao ? Math.round(totalCentavos * 0.1) : 0;
  const palavra = itens === 1 ? 'item' : 'itens';
  const cartao = temCartao ? 'com cartão' : 'sem cartão';
  return `${itens} ${palavra}: ${formatarReais(totalCentavos - desconto)} ${cartao}`;
}

console.log(resumoDaCompra(1, 4590, false));
console.log(resumoDaCompra(3, 12000, true));
console.log(resumoDaCompra(2, 3999, true));
